import React, { useContext } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { ExpenseContext } from '../context/ExpenseContext';
import { calculateDebts } from './BalancesScreen';
import EmptyState from '../components/EmptyState';

export default function HomeScreen({ navigation }) {
  const { expenses, roommates, settlements } = useContext(ExpenseContext);

  // Compute live totals from real state
  const totalSpent = expenses.reduce((sum, item) => sum + Number(item.amount || 0), 0);

  // Find the current user's net balance
  const userRoommate = roommates.find(r => r.isUser);
  const { balances } = calculateDebts(roommates, expenses, settlements);
  const userBalance = userRoommate ? (balances[userRoommate.id] || 0) : 0;

  // Get the 3 most recent expenses
  const recentExpenses = expenses.slice(0, 3);

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.contentContainer}>
      {/* Household Summary Card */}
      <View style={styles.summaryCard}>
        <Text style={styles.summaryLabel}>Total Household Spend</Text>
        <Text style={styles.summaryAmount}>${totalSpent.toFixed(2)}</Text>
        <Text style={styles.summarySub}>Split across {roommates.length} roommates</Text>

        {/* User's Net Balance Highlight */}
        <View style={styles.userBalanceContainer}>
          <Ionicons 
            name={userBalance >= 0 ? "arrow-up-circle" : "arrow-down-circle"} 
            size={20} 
            color={userBalance >= 0 ? theme.colors.primary : theme.colors.danger} 
          />
          <Text style={styles.userBalanceText}>
            {userBalance > 0.01 ? (
              <Text>You are owed <Text style={styles.bold}>${userBalance.toFixed(2)}</Text> overall</Text>
            ) : userBalance < -0.01 ? (
              <Text>You owe <Text style={styles.bold}>${Math.abs(userBalance).toFixed(2)}</Text> overall</Text>
            ) : (
              <Text>You are completely settled up!</Text>
            )}
          </Text>
        </View>

        <View style={styles.actionRow}>
          <TouchableOpacity 
            style={[styles.button, styles.primaryButton]}
            onPress={() => navigation.navigate('AddExpense')}
          >
            <Ionicons name="add" size={18} color="#FFFFFF" />
            <Text style={styles.primaryButtonText}>Add Expense</Text>
