import React, { useState, useContext } from 'react';
import { View, Text, StyleSheet, TextInput, TouchableOpacity, ScrollView, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { ExpenseContext } from '../context/ExpenseContext';

export default function AddExpenseScreen({ navigation }) {
  const { roommates, addExpense } = useContext(ExpenseContext);

  const [title, setTitle] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState(roommates[0]?.id || '1');
  const [splitBetween, setSplitBetween] = useState(roommates.map(r => r.id));
  const [receiptUri, setReceiptUri] = useState('');
  const [error, setError] = useState('');

  // Toggle roommate inclusion in the split
  const toggleSplitMember = (id) => {
    if (splitBetween.includes(id)) {
      if (splitBetween.length === 1) return; // Must keep at least 1 person
      setSplitBetween(splitBetween.filter(item => item !== id));
    } else {
      setSplitBetween([...splitBetween, id]);
    }
  };

  const handleSave = () => {
    if (!title.trim()) {
      setError('Please enter a description');
      return;
    }
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) {
      setError('Please enter a valid amount');
      return;
    }

    addExpense({
      title: title.trim(),
      amount: numAmount,
      paidBy,
      splitBetween,
      receiptUri: receiptUri.trim(),
    });

    navigation.goBack();
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      <Text style={styles.label}>Description</Text>
      <TextInput
        style={styles.input}
        placeholder="e.g. Groceries, Electricity, Wi-Fi"
        placeholderTextColor={theme.colors.textMuted}
        value={title}
        onChangeText={setTitle}
      />

      <Text style={styles.label}>Amount ($)</Text>
      <TextInput
        style={styles.input}
        placeholder="0.00"
        placeholderTextColor={theme.colors.textMuted}
        keyboardType="decimal-pad"
        value={amount}
        onChangeText={setAmount}
      />

      <Text style={styles.label}>Paid By</Text>
      <View style={styles.pillRow}>
        {roommates.map(r => (
          <TouchableOpacity
            key={r.id}
            style={[styles.pill, paidBy === r.id && styles.pillActive]}
            onPress={() => setPaidBy(r.id)}
          >
            <Text style={[styles.pillText, paidBy === r.id && styles.pillTextActive]}>{r.name}</Text>
          </TouchableOpacity>
        ))}
      </View>

      <Text style={styles.label}>Split Between</Text>
      <View style={styles.pillRow}>
        {roommates.map(r => {
          const isSelected = splitBetween.includes(r.id);
          return (
            <TouchableOpacity
              key={r.id}
              style={[styles.pill, isSelected && styles.pillActiveSecondary]}
              onPress={() => toggleSplitMember(r.id)}
            >
              <Ionicons 
                name={isSelected ? "checkbox-outline" : "square-outline"} 
                size={16} 
                color={isSelected ? theme.colors.primary : theme.colors.textMuted} 
              />
              <Text style={[styles.pillText, isSelected && styles.pillTextActiveSecondary]}>{r.name}</Text>
            </TouchableOpacity>
          );
        })}
      </View>

      <Text style={styles.label}>Receipt Photo (Image URL or Sample)</Text>
      <TextInput
        style={styles.input}
        placeholder="Paste image URL for receipt preview"
        placeholderTextColor={theme.colors.textMuted}
        value={receiptUri}
        onChangeText={setReceiptUri}
      />

      {receiptUri ? (
        <Image source={{ uri: receiptUri }} style={styles.receiptPreview} resizeMode="cover" />
      ) : null}

      <TouchableOpacity style={styles.saveButton} onPress={handleSave}>
        <Text style={styles.saveButtonText}>Save Expense</Text>
      </TouchableOpacity>
    </ScrollView>
  );
}

