import React, { useContext } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { ExpenseContext } from '../context/ExpenseContext';
import DebtCard from '../components/DebtCard';
import EmptyState from '../components/EmptyState';

// Helper function to calculate net balances and simplify active debts
export function calculateDebts(roommates, expenses, settlements) {
  const balances = {};
  roommates.forEach(r => {
    balances[r.id] = 0;
  });

  // 1. Process all expenses: Payer gets credited, split members get debited
  expenses.forEach(exp => {
    const amount = Number(exp.amount) || 0;
    const payerId = exp.paidBy;
    const splitIds = exp.splitBetween || [];

    if (splitIds.length === 0) return;

    const share = amount / splitIds.length;

    if (balances[payerId] !== undefined) {
      balances[payerId] += amount;
    }

    splitIds.forEach(id => {
      if (balances[id] !== undefined) {
        balances[id] -= share;
      }
    });
  });

  // 2. Process all manual settlements: Sender balance goes up, receiver goes down
  settlements.forEach(set => {
    const amount = Number(set.amount) || 0;
    const fromId = set.fromId;
    const toId = set.toId;

    if (balances[fromId] !== undefined) {
      balances[fromId] += amount;
    }
    if (balances[toId] !== undefined) {
      balances[toId] -= amount;
    }
  });

  // 3. Separate debtors and creditors to run transaction minimization
  const debtors = [];
  const creditors = [];

  Object.keys(balances).forEach(id => {
    const bal = balances[id];
    if (bal < -0.01) {
      debtors.push({ id, balance: bal });
    } else if (bal > 0.01) {
      creditors.push({ id, balance: bal });
    }
  });

  debtors.sort((a, b) => a.balance - b.balance);
  creditors.sort((a, b) => b.balance - a.balance);

  const debts = [];
  let dIdx = 0;
  let cIdx = 0;

  const activeDebtors = debtors.map(d => ({ ...d }));
  const activeCreditors = creditors.map(c => ({ ...c }));

  // Greedy matching to minimize transactions
  while (dIdx < activeDebtors.length && cIdx < activeCreditors.length) {
    const debtor = activeDebtors[dIdx];
    const creditor = activeCreditors[cIdx];

    const owedAmount = Math.min(Math.abs(debtor.balance), creditor.balance);

    if (owedAmount > 0.01) {
      debts.push({
        fromId: debtor.id,
        toId: creditor.id,
        amount: owedAmount,
      });
    }

    debtor.balance += owedAmount;
    creditor.balance -= owedAmount;

    if (Math.abs(debtor.balance) < 0.01) dIdx++;
    if (creditor.balance < 0.01) cIdx++;
  }

  return { balances, debts };
}

export default function BalancesScreen({ navigation }) {
  const { roommates, expenses, settlements, addSettlement, deleteSettlement } = useContext(ExpenseContext);

  const { balances, debts } = calculateDebts(roommates, expenses, settlements);

  const handleSettle = (fromId, toId, amount) => {
    addSettlement({
      fromId,
      toId,
      amount,
    });
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      {/* Net Balances Summary List */}
      <Text style={styles.sectionTitle}>Roommate Balances</Text>
      <View style={styles.balanceList}>
        {roommates.map(r => {
          const bal = balances[r.id] || 0;
          const isOwed = bal > 0.01;
          const owes = bal < -0.01;

          return (
            <View key={r.id} style={styles.balanceRow}>
              <View style={styles.roommateInfo}>
                <View style={[styles.avatar, r.isUser && styles.userAvatar]}>
                  <Text style={styles.avatarText}>{r.name[0]}</Text>
                </View>
                <Text style={styles.roommateName}>{r.name}</Text>
              </View>
              <Text style={[
                styles.balanceAmount,
                isOwed && styles.textOwed,
                owes && styles.textOwes
              ]}>
                {isOwed ? `is owed $${bal.toFixed(2)}` : owes ? `owes $${Math.abs(bal).toFixed(2)}` : 'settled up'}
              </Text>
            </View>
          );
        })}
      </View>

      {/* Simplified Debts Section */}
      <Text style={styles.sectionTitle}>Active Debts to Settle</Text>
      {debts.length === 0 ? (
        <EmptyState
          icon="checkmark-circle-outline"
          title="All Settled Up!"
          description="No outstanding household debts. Everyone is perfectly square."
          actionLabel="Log an Expense"
          onAction={() => navigation.navigate('AddExpense')}
        />
      ) : (
        debts.map((debt, index) => (
          <DebtCard
            key={`${debt.fromId}-${debt.toId}-${index}`}
            debt={debt}
            roommates={roommates}
            onSettle={handleSettle}
          />
        ))
      )}

      {/* History of Settlements */}
      {settlements && settlements.length > 0 ? (
        <View style={styles.historySection}>
          <Text style={styles.sectionTitle}>Recent Settlements</Text>
          {settlements.map(set => {
            const sender = roommates.find(r => r.id === set.fromId);
            const receiver = roommates.find(r => r.id === set.toId);
            return (
              <View key={set.id} style={styles.historyCard}>
                <Ionicons name="checkmark-circle" size={18} color={theme.colors.primary} />
                <Text style={styles.historyText}>
                  <Text style={styles.bold}>{sender?.name || 'Someone'}</Text> paid{' '}
                  <Text style={styles.bold}>{receiver?.name || 'Someone'}</Text>{' '}
                  <Text style={styles.bold}>${Number(set.amount).toFixed(2)}</Text>
                </Text>
              </View>
            );
          })}
        </View>
      ) : null}
    </ScrollView>
  );
}

