import React, { useState, useContext } from 'react';
import { View, Text, StyleSheet, TextInput, TouchableOpacity, ScrollView, Share } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';
import { ExpenseContext } from '../context/ExpenseContext';

export default function SettingsScreen() {
  const { roommates, expenses, settlements, saveRoommates, importHouseholdState } = useContext(ExpenseContext);
  const [newRoommateName, setNewRoommateName] = useState('');
  const [importPayload, setImportPayload] = useState('');
  const [statusMessage, setStatusMessage] = useState('');
  const [statusType, setStatusType] = useState('success'); // 'success' | 'error'

  // Add a new roommate to the household
  const handleAddRoommate = () => {
    if (!newRoommateName.trim()) return;
    const newRoommate = {
      id: 'room-' + Date.now(),
      name: newRoommateName.trim(),
      isUser: false,
    };
    saveRoommates([...roommates, newRoommate]);
    setNewRoommateName('');
    showStatus('Roommate added successfully!', 'success');
  };

  const showStatus = (msg, type = 'success') => {
    setStatusMessage(msg);
    setStatusType(type);
    setTimeout(() => setStatusMessage(''), 4000);
  };

  // Generate a Base64 payload representing the entire household state
  const generatePayload = () => {
    try {
      const state = { roommates, expenses, settlements };
      const jsonString = JSON.stringify(state);
      // UTF-8 safe base64 encoding
      const payload = btoa(unescape(encodeURIComponent(jsonString)));
      return payload;
    } catch (e) {
      console.error('Failed to generate payload', e);
      return '';
    }
  };

  // Share the payload using the native Share API
  const handleSharePayload = async () => {
    const payload = generatePayload();
    if (!payload) return;
    try {
      await Share.share({
        message: `Join my SplitFlat household! Import this state code in Settings:\n\n${payload}`,
        title: 'SplitFlat Household Invite',
      });
    } catch (error) {
      showStatus('Failed to share payload', 'error');
    }
  };

  // Import a household state from a pasted Base64 payload
  const handleImportPayload = () => {
    if (!importPayload.trim()) {
      showStatus('Please paste a valid state code', 'error');
      return;
    }
    try {
      // UTF-8 safe base64 decoding
      const decodedJson = decodeURIComponent(escape(atob(importPayload.trim())));
      const parsedState = JSON.parse(decodedJson);

      if (parsedState && Array.isArray(parsedState.roommates) && Array.isArray(parsedState.expenses)) {
        importHouseholdState(parsedState);
        setImportPayload('');
        showStatus('Household imported successfully!', 'success');
      } else {
        showStatus('Invalid payload format', 'error');
      }
    } catch (e) {
      showStatus('Failed to parse state code. Make sure it is copied correctly.', 'error');
    }
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      {statusMessage ? (
        <View style={[styles.statusBanner, statusType === 'error' && styles.statusBannerError]}>
          <Ionicons 
            name={statusType === 'success' ? "checkmark-circle" : "alert-circle"} 
            size={18} 
            color={statusType === 'success' ? theme.colors.primary : theme.colors.danger} 
          />
          <Text style={[styles.statusText, statusType === 'error' && styles.statusTextError]}>
            {statusMessage}
          </Text>
        </View>
      ) : null}

      {/* Roommate Management Section */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Manage Roommates</Text>
        <Text style={styles.sectionSubtitle}>Add or view members of this household.</Text>

        <View style={styles.addRoommateRow}>
          <TextInput
            style={styles.input}
            placeholder="Roommate's name..."
            placeholderTextColor={theme.colors.textMuted}
            value={newRoommateName}
            onChangeText={setNewRoommateName}
          />
          <TouchableOpacity style={styles.addButton} onPress={handleAddRoommate}>
            <Ionicons name="add" size={20} color="#FFFFFF" />
          </TouchableOpacity>
        </View>

        <View style={styles.roommateList}>
          {roommates.map(r => (
            <View key={r.id} style={styles.roommateRow}>
              <View style={styles.roommateInfo}>
                <View style={[styles.avatar, r.isUser && styles.userAvatar]}>
                  <Text style={styles.avatarText}>{r.name[0]}</Text>
                </View>
                <Text style={styles.roommateName}>{r.name} {r.isUser ? '(You)' : ''}</Text>
              </View>
              {r.isUser ? (
                <Text style={styles.userTag}>Owner</Text>
              ) : (
                <Text style={styles.memberTag}>Member</Text>
              )}
            </View>
          ))}
        </View>
      </View>

      {/* Invite & Sync Section */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Household Invite & Sync</Text>
        <Text style={styles.sectionSubtitle}>
          Generate a secure, offline-first payload to share your household state with roommates, or import an existing state.
        </Text>

        <TouchableOpacity style={styles.shareButton} onPress={handleSharePayload}>
          <Ionicons name="share-social-outline" size={18} color="#FFFFFF" />
          <Text style={styles.shareButtonText}>Share Household State</Text>
        </TouchableOpacity>

        <View style={styles.divider} />

        <Text style={styles.subLabel}>Import Household State</Text>
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Paste the state code shared by your roommate..."
          placeholderTextColor={theme.colors.textMuted}
          multiline
          numberOfLines={4}
