import React, { createContext, useState, useEffect } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { initialExpenses, initialRoommates, initialSettlements } from '../data/seedData';

export const ExpenseContext = createContext();

const STORAGE_KEYS = {
  EXPENSES: '@SplitFlat:expenses',
  ROOMMATES: '@SplitFlat:roommates',
  SETTLEMENTS: '@SplitFlat:settlements',
};

// Provider component that wraps state and handles AsyncStorage load/save cycles
export const ExpenseProvider = ({ children }) => {
  const [expenses, setExpenses] = useState(initialExpenses);
  const [roommates, setRoommates] = useState(initialRoommates);
  const [settlements, setSettlements] = useState(initialSettlements);
  const [isLoading, setIsLoading] = useState(true);

  // Load persisted data on mount
  useEffect(() => {
    const loadStoredData = async () => {
      try {
        const storedExp = await AsyncStorage.getItem(STORAGE_KEYS.EXPENSES);
        const storedRoom = await AsyncStorage.getItem(STORAGE_KEYS.ROOMMATES);
        const storedSettlements = await AsyncStorage.getItem(STORAGE_KEYS.SETTLEMENTS);

        if (storedExp) setExpenses(JSON.parse(storedExp));
        if (storedRoom) setRoommates(JSON.parse(storedRoom));
        if (storedSettlements) setSettlements(JSON.parse(storedSettlements));
      } catch (error) {
        console.error('Failed to load local data', error);
      } finally {
        setIsLoading(false);
      }
    };
    loadStoredData();
  }, []);

  // Save expenses when updated
  const saveExpenses = async (newExpenses) => {
    setExpenses(newExpenses);
    try {
      await AsyncStorage.setItem(STORAGE_KEYS.EXPENSES, JSON.stringify(newExpenses));
    } catch (error) {
      console.error('Failed to save expenses', error);
    }
  };

  // Save roommates when updated
  const saveRoommates = async (newRoommates) => {
    setRoommates(newRoommates);
    try {
      await AsyncStorage.setItem(STORAGE_KEYS.ROOMMATES, JSON.stringify(newRoommates));
    } catch (error) {
      console.error('Failed to save roommates', error);
    }
  };

  // Save settlements when updated
  const saveSettlements = async (newSettlements) => {
    setSettlements(newSettlements);
    try {
      await AsyncStorage.setItem(STORAGE_KEYS.SETTLEMENTS, JSON.stringify(newSettlements));
    } catch (error) {
      console.error('Failed to save settlements', error);
    }
  };

  const addExpense = (expenseData) => {
    const newExpense = {
      id: 'exp-' + Date.now(),
      date: new Date().toISOString(),
      ...expenseData,
    };
    saveExpenses([newExpense, ...expenses]);
  };

  const deleteExpense = (id) => {
    const filtered = expenses.filter(item => item.id !== id);
    saveExpenses(filtered);
  };

  const addSettlement = (settlementData) => {
    const newSettlement = {
      id: 'set-' + Date.now(),
      date: new Date().toISOString(),
      ...settlementData,
    };
    saveSettlements([newSettlement, ...settlements]);
  };

  // Overwrites current state with an imported household payload
  const importHouseholdState = (newState) => {
    if (newState.expenses) saveExpenses(newState.expenses);
    if (newState.roommates) saveRoommates(newState.roommates);
    if (newState.settlements) saveSettlements(newState.settlements || []);
  };

  return (
    <ExpenseContext.Provider 
      value={{
        expenses,
        roommates,
        settlements,
        isLoading,
        addExpense,
        deleteExpense,
        addSettlement,
        saveRoommates,
        importHouseholdState,
      }}
    >
      {children}
    </ExpenseContext.Provider>
  );
};

