import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { theme } from '../theme';

// Card representing a simplified debt between two roommates with inline confirmation
export default function DebtCard({ debt, roommates, onSettle }) {
  const [isConfirming, setIsConfirming] = useState(false);

  const debtor = roommates.find(r => r.id === debt.fromId);
  const creditor = roommates.find(r => r.id === debt.toId);

  if (!debtor || !creditor) return null;

  const debtorName = debtor.isUser ? 'You' : debtor.name;
  const creditorName = creditor.isUser ? 'You' : creditor.name;

  const handleSettlePress = () => {
    setIsConfirming(true);
  };

  const handleConfirm = () => {
    onSettle(debt.fromId, debt.toId, debt.amount);
    setIsConfirming(false);
  };

  return (
    <View style={styles.card}>
      {!isConfirming ? (
        <View style={styles.row}>
          <View style={styles.avatarRow}>
            <View style={[styles.avatar, debtor.isUser && styles.userAvatar]}>
              <Text style={styles.avatarText}>{debtor.name[0]}</Text>
            </View>
            <Ionicons name="arrow-forward" size={16} color={theme.colors.textMuted} style={styles.arrow} />
            <View style={[styles.avatar, creditor.isUser && styles.userAvatar]}>
              <Text style={styles.avatarText}>{creditor.name[0]}</Text>
            </View>
          </View>

          <View style={styles.details}>
            <Text style={styles.debtText}>
              <Text style={styles.bold}>{debtorName}</Text> owes <Text style={styles.bold}>{creditorName}</Text>
            </Text>
            <Text style={styles.amount}>${debt.amount.toFixed(2)}</Text>
          </View>

          <TouchableOpacity style={styles.settleButton} onPress={handleSettlePress}>
            <Text style={styles.settleButtonText}>Settle</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <View style={styles.confirmContainer}>
          <Text style={styles.confirmTitle}>Confirm Cash Settlement?</Text>
          <Text style={styles.confirmSub}>
            Did {debtorName} pay {creditorName} ${debt.amount.toFixed(2)}?
          </Text>
          <View style={styles.confirmActions}>
            <TouchableOpacity 
              style={[styles.actionButton, styles.cancelButton]} 
              onPress={() => setIsConfirming(false)}
            >
              <Text style={styles.cancelButtonText}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity 
              style={[styles.actionButton, styles.confirmButton]} 
              onPress={handleConfirm}
            >
              <Text style={styles.confirmButtonText}>Yes, Settled</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}
    </View>
  );
}

